-- Zones de Brumath d'après « Brumath adresses par zone.xlsx » (27/10/2026) : UNE ligne par rue du fichier, zones 1 à 7
-- (1 = sud, on finit par la 7 = ouest). Une rue coupée entre deux zones (Millerand, de l'Herbe) a les deux dans `zones`.
-- Source unique des zones : remplace `referentiel_rues.zone / zones` (anciennes colonnes gardées, plus lues).
create table if not exists public.zones_rues (
  company_id uuid not null references public.companies(id) on delete cascade,
  commune_cle text not null,
  rue_cle text not null,
  rue text not null,
  zones text[] not null check (cardinality(zones) >= 1),
  maj_le timestamptz not null default now(),
  primary key (company_id, commune_cle, rue_cle)
);
alter table public.zones_rues enable row level security;
create policy zones_rues_select on public.zones_rues for select to authenticated
  using (company_id = (select current_company_id()));
create policy zones_rues_ecrire on public.zones_rues for all to authenticated
  using (company_id = (select current_company_id()) and ((select is_president()) or (select has_permission('planning.tournees', 'update'))))
  with check (company_id = (select current_company_id()) and ((select is_president()) or (select has_permission('planning.tournees', 'update'))));

insert into public.zones_rues (company_id, commune_cle, rue_cle, rue, zones)
select c.id, 'brumath', v.k, v.rue, v.zs::text[]
